package fraymus.workspace;
import org.json.*;
import java.nio.file.Path;
import java.time.Instant;
import java.util.*;

/** Fit, separate calibration, freeze, then prospective paired native evaluation. */
final class UsefulStudy072 {
 static final String PROTOCOL="useful-observation-072-v1";static final int TOTAL=666;
 private static final class Identity{static final String VALUE=implementation();}
 static String source(){return Identity.VALUE;}
 private static String implementation(){try(var in=UsefulStudy072.class.getResourceAsStream("UsefulStudy072.class")){return MeasurementStore.hash(PROTOCOL+UsefulTrial072.source()+MapDefinition.sha(in.readAllBytes()));}catch(Exception e){throw new IllegalStateException(e);}}
 static JSONObject task(Random random,int regime,int i){return new JSONObject().put("angleDeg",12+20*random.nextDouble()).put("frictionRatio",regime==0?.85+.14*random.nextDouble():1.01+.19*random.nextDouble()).put("centerM",.02+.34*random.nextDouble()).put("halfWidthM",new double[]{.012,.024,.045}[i%3]);}
 private static JSONArray trainingRaw(String phase){
  if(!Set.of("fit","calibration").contains(phase))throw new IllegalArgumentException("Unknown training phase");var random=new Random(phase.equals("fit")?72001:72002);int target=phase.equals("fit")?6:9;var rows=new JSONArray();
  for(int regime=0;regime<2;regime++){int predicted=0,measured=0;for(int i=0;i<10000&&(predicted<target||measured<target);i++){var t=task(random,regime,i);var d=UsefulPolicy072.initial(t).getJSONObject("decisions").getJSONObject("blind");boolean measuredFirst=d.getBoolean("recover");if(!d.getBoolean("execute")||measuredFirst&&measured>=target||!measuredFirst&&predicted>=target)continue;rows.put(new JSONObject().put("task",t).put("cell",Uncertainty071.cell(t,d)).put("draw",i));if(measuredFirst)measured++;else predicted++;}if(predicted!=target||measured!=target)throw new IllegalStateException("Training cell could not be filled");}return rows;
 }
 private static JSONArray casesRaw(String phase){
  long seed=switch(phase){case "clean"->72003;case "disturbed"->72004;case "unsupported"->72005;default->throw new IllegalArgumentException("Unknown phase");};var random=new Random(seed);var rows=new JSONArray();boolean outside=phase.equals("unsupported");
  for(int regime=0;regime<2;regime++)for(int i=0;i<(outside?6:phase.equals("disturbed")?30:24);i++){var t=task(random,regime,i);if(outside)switch(i%3){case 0->t.put("angleDeg",10);case 1->t.put("angleDeg",34);case 2->t.put("frictionRatio",1);}String family=phase.equals("disturbed")?AdaptiveStudy070.FAMILIES.get(i%5):"none";rows.put(new JSONObject().put("task",t).put("disturbance",family).put("event",AdaptiveRamp070.event(family,phase.equals("disturbed")?(i/5)%2:0,phase.equals("disturbed")?((i/10)+regime)%2:0)));}return rows;
 }
 private static final class Definitions{static final JSONObject DATA=definitions();}
 private static JSONObject definitions(){var out=new JSONObject();for(String phase:List.of("fit","calibration"))out.put(phase,trainingRaw(phase));for(String phase:List.of("clean","disturbed","unsupported"))out.put(phase,casesRaw(phase));return out;}
 static JSONArray training(String phase){if(!Set.of("fit","calibration").contains(phase))throw new IllegalArgumentException("Unknown training phase");return new JSONArray(Definitions.DATA.getJSONArray(phase).toString());}
 static JSONArray cases(String phase){if(!Set.of("clean","disturbed","unsupported").contains(phase))throw new IllegalArgumentException("Unknown evaluation phase");return new JSONArray(Definitions.DATA.getJSONArray(phase).toString());}
 static JSONArray parityCases(){var out=new JSONArray();var found=new HashSet<String>();for(Object raw:training("fit")){var row=(JSONObject)raw;String cell=row.getString("cell");if(Set.of("accelerating-predicted","slowing-measured").contains(cell)&&found.add(cell))for(String method:List.of("blind","adaptive","uncertain"))out.put(new JSONObject().put("task",row.getJSONObject("task")).put("method",method));}if(out.length()!=6)throw new IllegalStateException("Parity cells incomplete");return out;}
 static JSONObject manifest(){var out=new JSONObject().put("protocol",PROTOCOL).put("source",source()).put("nativeSource",UsefulTrial072.source()).put("total",TOTAL).put("methods",new JSONArray(UsefulPolicy072.METHODS)).put("fit",training("fit")).put("calibration",training("calibration")).put("parity",parityCases()).put("nominalCoverage",.90).put("scaleFloorM",.002).put("inferenceFee",.005).put("cleanCoverageGate",.85).put("cleanUtilityGain",.005).put("requiredSensingReductionVersusUncertain",true).put("disturbedUtilityTolerance",.03).put("disturbedAllowedLoss",1).put("hypotheticalScenarios",ObservationSchedule070.scenarios()).put("residualGridWeights",new JSONArray(new double[]{.25,.50,.25})).put("speedFloorMps",.01).put("scalarLabelFee",.03).put("newPolicyFee",.01).put("controllerAuthority",false);for(String phase:List.of("clean","disturbed","unsupported"))out.put(phase,cases(phase));return out;}
 static JSONObject oldDecision(JSONObject task,String method){return UncertainPolicy071.initial(task).getJSONObject("decisions").getJSONObject(method);}
 static double parity(JSONObject old,JSONObject now){
  UncertainTrial071.verify(old);UsefulTrial072.verify(now);double delta=AdaptiveStudy070.compareSamples(old,now,45);
  for(String key:List.of("correctionPlan","laterPlan"))if(old.has(key)!=now.has(key)||old.has(key)&&!old.getJSONObject(key).similar(now.getJSONObject(key)))throw new IllegalStateException("Original071 plan changed");
  if(old.has("schedule071")&&!old.getJSONObject("schedule071").similar(now.getJSONObject("schedule072")))throw new IllegalStateException("Original071 scheduler changed");return delta;
 }
 static JSONObject coverage(JSONArray rows){
  int count=0,joint=0,distance=0,end=0;double width=0,speedWidth=0;var cells=new JSONObject();
  for(String cell:Uncertainty071.CELLS)cells.put(cell,new JSONObject().put("count",0).put("jointCovered",0).put("distanceCovered",0).put("terminalCovered",0));
  for(Object raw:rows){var row=(JSONObject)raw;if(!row.has("coverage072"))continue;var c=row.getJSONObject("coverage072");count++;boolean j=c.getBoolean("jointCovered"),d=c.getBoolean("distanceCovered"),e=c.getBoolean("terminalCovered");if(j)joint++;if(d)distance++;if(e)end++;width+=c.getDouble("terminalWidthM");speedWidth+=c.getDouble("terminalSpeedWidthMps");var cell=cells.getJSONObject(c.getString("cell"));cell.put("count",cell.getInt("count")+1).put("jointCovered",cell.getInt("jointCovered")+(j?1:0)).put("distanceCovered",cell.getInt("distanceCovered")+(d?1:0)).put("terminalCovered",cell.getInt("terminalCovered")+(e?1:0));}
  return new JSONObject().put("count",count).put("jointCovered",joint).put("distanceCovered",distance).put("terminalCovered",end).put("jointCoverage",count==0?JSONObject.NULL:joint/(double)count).put("distanceCoverage",count==0?JSONObject.NULL:distance/(double)count).put("terminalCoverage",count==0?JSONObject.NULL:end/(double)count).put("meanTerminalWidthM",count==0?JSONObject.NULL:width/count).put("meanTerminalSpeedWidthMps",count==0?JSONObject.NULL:speedWidth/count).put("cells",cells).put("truth","Paired blind future, four position and four speed quantities");
 }
 static JSONObject evaluation(JSONArray rows,String phase){
  var out=UsefulPolicy072.evaluate(rows,true);double prefix=0;int suppressed=0,forced=0,retimed=0,looks=0,skips=0,corrections=0;var choices=new JSONObject().put("skip",0).put("92",0).put("116",0).put("140",0);var pairs=new JSONObject();for(String m:List.of("blind","adaptive","uncertain","simple"))pairs.put(m,new JSONObject().put("saved",0).put("harmed",0));var reasons=new JSONObject();
  for(Object raw:rows){var row=(JSONObject)raw;var rs=row.getJSONObject("results");if(!rs.getJSONObject("blind").has("record"))continue;var blind=rs.getJSONObject("blind").getJSONObject("record");for(String m:UsefulPolicy072.METHODS)prefix=Math.max(prefix,AdaptiveStudy070.prefixParity(blind,rs.getJSONObject(m).getJSONObject("record")));
   var rec=rs.getJSONObject("useful").getJSONObject("record");int tick=rec.getJSONObject("schedule072").getInt("selectedTick"),old=rs.getJSONObject("uncertain").getJSONObject("record").getJSONObject("schedule072").getInt("selectedTick");if(tick<0)skips++;else looks++;if(old>0&&tick<0)suppressed++;if(old<0&&tick>0)forced++;if(old>0&&tick>0&&old!=tick)retimed++;String key=tick<0?"skip":Integer.toString(tick);choices.put(key,choices.getInt(key)+1);if(rec.has("laterReceipt"))corrections++;if(rec.has("laterPlan")){String reason=rec.getJSONObject("laterPlan").getString("reason");reasons.put(reason,reasons.optInt(reason)+1);}
   boolean current=rs.getJSONObject("useful").getJSONObject("outcome").getBoolean("success");for(String m:pairs.keySet()){boolean previous=rs.getJSONObject(m).getJSONObject("outcome").getBoolean("success");var p=pairs.getJSONObject(m);if(current&&!previous)p.put("saved",p.getInt("saved")+1);if(previous&&!current)p.put("harmed",p.getInt("harmed")+1);}
  }
  out.put("diagnostics",new JSONObject().put("suppressedLooks",suppressed).put("forcedLooks",forced).put("retimedLooks",retimed).put("looks",looks).put("skips",skips).put("actualCorrections",corrections).put("correctionReasons",reasons).put("goals",pairs).put("choices",choices).put("prefixMaximumDelta",prefix)).put("coverage",coverage(rows)).put("phase",phase);
  var groups=new JSONObject();for(String name:List.of("accelerating","slowing","predicted","measured","brake","lift","push","spin","after-last")){var subset=new JSONArray();for(Object raw:rows){var row=(JSONObject)raw;boolean match=switch(name){case "accelerating"->row.getJSONObject("task").getDouble("frictionRatio")<1;case "slowing"->row.getJSONObject("task").getDouble("frictionRatio")>1;case "predicted"->!row.getJSONObject("plan").getJSONObject("decisions").getJSONObject("blind").getBoolean("recover");case "measured"->row.getJSONObject("plan").getJSONObject("decisions").getJSONObject("blind").getBoolean("recover");default->row.getString("disturbance").equals(name);};if(match)subset.put(row);}if(!subset.isEmpty())groups.put(name,UsefulPolicy072.evaluate(subset,false).put("coverage",coverage(subset)));}
  return out.put("subgroups",groups).put("qualified",qualifies(out,phase));
 }
 static boolean qualifies(JSONObject e,String phase){
  if(!Set.of("clean","disturbed").contains(phase))return false;boolean clean=phase.equals("clean");var m=e.getJSONObject("methods");var u=m.getJSONObject("useful");
  for(String other:List.of("adaptive","uncertain","simple")){var o=m.getJSONObject(other);double gain=e.getJSONObject("pairedUsefulMinus").getJSONObject(other).getDouble("meanDelta");if(u.getInt("successes")<o.getInt("successes")-(clean?0:1)||gain<(clean?(other.equals("uncertain")?.005:0):-.03)-1e-12)return false;}
  return !clean||e.getJSONObject("coverage").getDouble("jointCoverage")>=.85-1e-12;
 }
 static boolean qualified(JSONObject job){int looks=0,skip=0,saved=0,used=0,old=0;for(String phase:List.of("clean","disturbed")){var e=job.getJSONObject(phase+"Evaluation072");if(!e.getBoolean("qualified"))return false;var d=e.getJSONObject("diagnostics");looks+=d.getInt("looks");skip+=d.getInt("skips");saved+=d.getJSONObject("goals").getJSONObject("blind").getInt("saved");used+=e.getJSONObject("methods").getJSONObject("useful").getInt("extraObservations");old+=e.getJSONObject("methods").getJSONObject("uncertain").getInt("extraObservations");}return looks>0&&skip>0&&saved>0&&used<old;}
 static JSONObject trainingCosts(JSONObject job){double utility=0,cost=.08,ms=0;int observations=0,actions=0,misses=0;for(String phase:List.of("fit","calibration"))for(Object raw:job.getJSONArray(phase+"072")){var o=((JSONObject)raw).getJSONObject("outcome");utility+=o.getDouble("utility")-.245;cost+=o.getDouble("logicalCost")+.245;observations+=o.getInt("observations");actions+=o.getInt("actions");if(!o.getBoolean("success"))misses++;ms+=o.getDouble("nativeWallMillis");}return new JSONObject().put("runs",60).put("misses",misses).put("actions",actions).put("controllerObservations",observations).put("labelSampleTimes",240).put("labelScalars",480).put("logicalCost",cost).put("utility",utility-.08).put("nativeWallMillis",ms).put("fitAndCalibrationMillis",job.getDouble("fitMillis072")).put("scope","Original blind operations/misses plus eight scalar labels at .03 and .005 residual calculation each run; total fixed fitting/calibration .08. Label units are accounting assumptions; not extra sensor frames.");}
 static void advance(JSONObject j,FraynixOutcome061.Progress p,String text)throws Exception{j.put("progress",j.getInt("progress")+1);p.save(text);}
 static void run(JSONObject job,Path dir,Runnable cancel,FraynixOutcome061.Progress progress)throws Exception{
  job.put("manifest072",manifest()).put("progress",0).put("total",TOTAL).put("nativeExecutions",0).put("parity072",new JSONArray());for(String phase:List.of("fit","calibration","clean","disturbed","unsupported"))job.put(phase+"072",new JSONArray());progress.save("Uncertainty contract saved before training");
  for(String phase:List.of("fit","calibration"))for(Object raw:training(phase)){cancel.run();var spec=(JSONObject)raw;var t=spec.getJSONObject("task");var d=UsefulPolicy072.initial(t).getJSONObject("decisions").getJSONObject("blind");var row=WorldFrames.copy(spec).put("plannedAt",Instant.now().toString()).put("decision",d);job.getJSONArray(phase+"072").put(row);progress.save("Training blind plan saved");var record=UncertainTrial071.run(t,d,AdaptiveRamp070.event("none",0,0),dir,cancel,partial->{row.put("pending",partial);progress.save("Training first plan saved before action");},null);row.remove("pending");row.put("record",record).put("outcome",UncertainPolicy071.outcome(t,d,record));job.put("nativeExecutions",job.getInt("nativeExecutions")+1);advance(job,progress,phase+": independent native residual retained");}
  cancel.run();long at=System.nanoTime();job.put("model072",StateUncertainty072.fit(job.getJSONArray("fit072"),job.getJSONArray("calibration072"))).put("fitMillis072",(System.nanoTime()-at)/1e6).put("modelFrozenAt",Instant.now().toString());job.put("trainingCosts072",trainingCosts(job));progress.save("State and distance models calibrated and frozen before reserved evaluation");
  for(Object raw:parityCases()){cancel.run();var spec=(JSONObject)raw;var t=spec.getJSONObject("task");String m=spec.getString("method");var old=UncertainTrial071.run(t,oldDecision(t,m),AdaptiveRamp070.event("none",0,0),dir,cancel,partial->{},m.equals("uncertain")?job.getJSONObject("model072").getJSONObject("distance"):null);var now=UsefulTrial072.run(t,UsefulPolicy072.initial(t).getJSONObject("decisions").getJSONObject(m),AdaptiveRamp070.event("none",0,0),dir,cancel,partial->{},m.equals("uncertain")?job.getJSONObject("model072"):null);job.getJSONArray("parity072").put(new JSONObject().put("spec",spec).put("original",old).put("adapter",now).put("maximumDelta",parity(old,now)));job.put("nativeExecutions",job.getInt("nativeExecutions")+2);advance(job,progress,"Exact071 baseline parity retained");}
  for(String phase:List.of("clean","disturbed","unsupported"))for(Object raw:cases(phase)){cancel.run();var spec=(JSONObject)raw;var t=spec.getJSONObject("task");var row=WorldFrames.copy(spec).put("plannedAt",Instant.now().toString()).put("plan",UsefulPolicy072.initial(t)).put("results",new JSONObject());job.getJSONArray(phase+"072").put(row);progress.save("Five held-out decisions saved before execution");for(String method:UsefulPolicy072.METHODS){cancel.run();var d=row.getJSONObject("plan").getJSONObject("decisions").getJSONObject(method);var result=new JSONObject();row.getJSONObject("results").put(method,result);JSONObject record=null;if(d.getBoolean("execute")){record=UsefulTrial072.run(t,d,row.getJSONObject("event"),dir,cancel,partial->{result.put("pending",partial);progress.save("Held-out source-bound plan saved before action");},Set.of("uncertain","simple","useful").contains(method)?job.getJSONObject("model072"):null);result.remove("pending");result.put("record",record);job.put("nativeExecutions",job.getInt("nativeExecutions")+1);}result.put("outcome",UsefulPolicy072.outcome(t,d,record));advance(job,progress,phase+": "+method+" actual outcome retained");}if(row.getJSONObject("results").getJSONObject("blind").has("record"))row.put("coverage072",StateUncertainty072.coverage(row.getJSONObject("results").getJSONObject("blind").getJSONObject("record"),job.getJSONObject("model072")));}
  for(String phase:List.of("clean","disturbed","unsupported"))job.put(phase+"Evaluation072",evaluation(job.getJSONArray(phase+"072"),phase));job.put("accepted",qualified(job)).put("reason","Useful observation and all outcome costs measured; no automatic promotion");audit(job);progress.save("Reserved uncertainty evaluation verified");
 }
 static void boundTraining(JSONObject record,JSONObject task,JSONObject decision,Instant planned,Set<String> ids){UncertainTrial071.verify(record);if(!record.getJSONObject("task").similar(task)||!record.getJSONObject("decision").similar(decision)||!record.getJSONObject("disturbance").similar(AdaptiveRamp070.event("none",0,0))||Instant.parse(record.getString("startedAt")).isBefore(planned)||!ids.add(record.getString("id")))throw new IllegalStateException("Training source binding differs");}
 static void boundRecord(JSONObject record,JSONObject task,JSONObject decision,JSONObject event,Instant planned,Set<String> ids){UsefulTrial072.verify(record);if(!record.getJSONObject("task").similar(task)||!record.getJSONObject("decision").similar(decision)||!record.getJSONObject("disturbance").similar(event)||Instant.parse(record.getString("startedAt")).isBefore(planned)||!ids.add(record.getString("id")))throw new IllegalStateException("Native source binding or chronology differs");}
 static void audit(JSONObject job){
  var oldTuples=new HashSet<String>();for(String phase:List.of("calibration","clean","disturbed","unsupported"))for(Object raw:CalibrationStudy068.cases(phase))oldTuples.add(WorldFrames.hash(((JSONObject)raw).getJSONObject("task")));
  for(String phase:List.of("clean","disturbed","unsupported")){for(Object raw:LaterStudy069.cases(phase))oldTuples.add(WorldFrames.hash(((JSONObject)raw).getJSONObject("task")));for(Object raw:AdaptiveStudy070.cases(phase))oldTuples.add(WorldFrames.hash(((JSONObject)raw).getJSONObject("task")));}
  for(String phase:List.of("fit","calibration","clean","disturbed","unsupported"))for(Object raw:job.getJSONArray(phase+"072"))if(oldTuples.contains(WorldFrames.hash(((JSONObject)raw).getJSONObject("task"))))throw new IllegalStateException("Old evaluation tuple reused");
  for(String phase:List.of("fit","calibration","clean","disturbed","unsupported"))for(Object raw:Set.of("fit","calibration").contains(phase)?UncertainStudy071.training(phase):UncertainStudy071.cases(phase))oldTuples.add(WorldFrames.hash(((JSONObject)raw).getJSONObject("task")));
  for(String phase:List.of("fit","calibration","clean","disturbed","unsupported"))for(Object raw:job.getJSONArray(phase+"072"))if(oldTuples.contains(WorldFrames.hash(((JSONObject)raw).getJSONObject("task"))))throw new IllegalStateException("Published task reused");
  if(!manifest().similar(job.getJSONObject("manifest072")))throw new IllegalStateException("Uncertainty protocol changed");var ids=new HashSet<String>();var tuples=new HashSet<String>();int count=0;Instant frozen=Instant.parse(job.getString("modelFrozenAt"));
  for(String phase:List.of("fit","calibration")){var specs=training(phase);var rows=job.getJSONArray(phase+"072");if(rows.length()!=specs.length())throw new IllegalStateException("Training incomplete");for(int i=0;i<rows.length();i++){var row=rows.getJSONObject(i);var spec=specs.getJSONObject(i);var t=spec.getJSONObject("task");var d=UsefulPolicy072.initial(t).getJSONObject("decisions").getJSONObject("blind");if(!row.getJSONObject("task").similar(t)||!row.getString("cell").equals(spec.getString("cell"))||row.getInt("draw")!=spec.getInt("draw")||!row.getJSONObject("decision").similar(d)||!tuples.add(WorldFrames.hash(t))||row.has("pending"))throw new IllegalStateException("Training partition changed");var rec=row.getJSONObject("record");boundTraining(rec,t,d,Instant.parse(row.getString("plannedAt")),ids);if(Instant.parse(rec.getString("observedAt")).isAfter(frozen)||!UncertainPolicy071.outcome(t,d,rec).similar(row.getJSONObject("outcome")))throw new IllegalStateException("Training cost or freeze order changed");count++;}}
  if(!StateUncertainty072.fit(job.getJSONArray("fit072"),job.getJSONArray("calibration072")).similar(job.getJSONObject("model072"))||!trainingCosts(job).similar(job.getJSONObject("trainingCosts072"))||!Double.isFinite(job.getDouble("fitMillis072"))||job.getDouble("fitMillis072")<0)throw new IllegalStateException("Frozen fit/calibration evidence differs");
  var specs=parityCases();var parityRows=job.getJSONArray("parity072");if(parityRows.length()!=6)throw new IllegalStateException("Parity incomplete");for(int i=0;i<6;i++){var p=parityRows.getJSONObject(i);var s=specs.getJSONObject(i);var t=s.getJSONObject("task");String method=s.getString("method");var a=p.getJSONObject("original");var b=p.getJSONObject("adapter");if(method.equals("uncertain")&&(!a.getJSONObject("uncertaintyModel").similar(job.getJSONObject("model072").getJSONObject("distance"))||!b.getJSONObject("uncertaintyModel").similar(job.getJSONObject("model072"))))throw new IllegalStateException("Parity model differs from frozen bundle");if(!s.similar(p.getJSONObject("spec"))||!a.getJSONObject("task").similar(t)||!a.getJSONObject("decision").similar(oldDecision(t,method))||!a.getJSONObject("disturbance").similar(AdaptiveRamp070.event("none",0,0))||!ids.add(a.getString("id"))||parity(a,b)!=p.getDouble("maximumDelta"))throw new IllegalStateException("Parity changed");boundRecord(b,t,UsefulPolicy072.initial(t).getJSONObject("decisions").getJSONObject(method),AdaptiveRamp070.event("none",0,0),frozen,ids);count+=2;}
  for(String phase:List.of("clean","disturbed","unsupported")){var rows=job.getJSONArray(phase+"072");var expected=cases(phase);if(rows.length()!=expected.length())throw new IllegalStateException("Held-out set changed");for(int i=0;i<rows.length();i++){var row=rows.getJSONObject(i);var spec=expected.getJSONObject(i);var t=spec.getJSONObject("task");if(!t.similar(row.getJSONObject("task"))||!spec.getJSONObject("event").similar(row.getJSONObject("event"))||!spec.getString("disturbance").equals(row.getString("disturbance"))||!tuples.add(WorldFrames.hash(t))||!UsefulPolicy072.initial(t).similar(row.getJSONObject("plan"))||Instant.parse(row.getString("plannedAt")).isBefore(frozen)||!row.getJSONObject("results").keySet().equals(new HashSet<>(UsefulPolicy072.METHODS)))throw new IllegalStateException("Held-out identity or frozen-model chronology differs");for(String method:UsefulPolicy072.METHODS){var result=row.getJSONObject("results").getJSONObject(method);var d=row.getJSONObject("plan").getJSONObject("decisions").getJSONObject(method);var rec=result.optJSONObject("record");if(result.has("pending"))throw new IllegalStateException("Pending evaluation");if(d.getBoolean("execute")){if(rec==null||phase.equals("unsupported"))throw new IllegalStateException("Missing/unsupported native execution");boundRecord(rec,t,d,row.getJSONObject("event"),Instant.parse(row.getString("plannedAt")),ids);if(Set.of("uncertain","simple","useful").contains(method)&&!rec.getJSONObject("uncertaintyModel").similar(job.getJSONObject("model072")))throw new IllegalStateException("Per-task model differs from frozen model");count++;}else if(rec!=null)throw new IllegalStateException("Refusal invented motion");if(!UsefulPolicy072.outcome(t,d,rec).similar(result.getJSONObject("outcome")))throw new IllegalStateException("Outcome costs changed");}var blind=row.getJSONObject("results").getJSONObject("blind").optJSONObject("record");if(blind!=null){if(!StateUncertainty072.coverage(blind,job.getJSONObject("model072")).similar(row.getJSONObject("coverage072")))throw new IllegalStateException("Coverage uses different truth");}else if(row.has("coverage072"))throw new IllegalStateException("Refused task has coverage truth");}if(!evaluation(rows,phase).similar(job.getJSONObject(phase+"Evaluation072")))throw new IllegalStateException("Held-out metrics differ");}
  if(job.getInt("nativeExecutions")!=count||job.getInt("progress")!=TOTAL||job.getInt("total")!=TOTAL||job.getBoolean("accepted")!=qualified(job))throw new IllegalStateException("Counts or qualification changed");
 }
 static JSONObject summary(JSONObject job){var out=new JSONObject().put("jobId",job.getString("id")).put("status",job.getString("status")).put("nativeExecutions",job.optInt("nativeExecutions"));if(job.has("model072"))out.put("modelSha256",job.getJSONObject("model072").getJSONObject("state").getString("sha256")).put("modelFrozenAt",job.getString("modelFrozenAt")).put("trainingCosts",job.getJSONObject("trainingCosts072")).put("modelScope",job.getJSONObject("model072").getJSONObject("state").getString("scope"));if(job.has("cleanEvaluation072"))for(String phase:List.of("clean","disturbed","unsupported"))out.put(phase,job.getJSONObject(phase+"Evaluation072"));if(job.has("accepted"))out.put("qualified",job.getBoolean("accepted"));return out;}
}
